        var tagged = cv.extractAndTagViolations([{ name: 'gate', logs: log }], diff);

        var crap = tagged.filter(function(v) { return v.rule === 'method_size'; });
        assert.equal(crap.length, 1, 'the crap4j detail line still parses exactly once');
