function ghErrorViolations(line, checkName) {
    var segments = String(line).split(/##\[error\]\s?/);
    var out = [];
    for (var i = 1; i < segments.length; i++) {
        var msg = segments[i].trim();
        if (!msg) continue;
        out.push({
            check: checkName,
            rule: 'error',
            path: findPathToken(msg),
            line: null,
            detail: msg
        });
    }
    return out;
}

