    // matches the last directory level (leftmost-match semantics).
    var m = stripped.match(/[A-Za-z0-9_.\-\/\\]+\.[A-Za-z0-9]+/);
    if (!m) return null;
    var token = [REDACTED:Sensitive Value]];
